            Describe.Lean(DescribeId.Create("mem-tuples"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.mem_tuples"), H("mem tuples"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Induction proves that every coordinatewise-valid tuple occurs in the enumeration."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("all-pivots"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.allPivots"), H("allPivots"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every selection of observation rows and reachability columns is listed in a fixed order. This transparent exhaustive algorithm is not claimed to be efficient for large dimensions."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("mem-all-pivots"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.mem_allPivots"), H("mem allPivots"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("No finite candidate pivot is omitted from the search space."))), DescribeRole.Theorem),
