            Describe.Lean(DescribeId.Create("acceptable"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.acceptable"), H("acceptable"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The data-only Boolean test checks a nonzero determinant, nonnegative entrywise uncertainty, and a strict inverse-noise margin."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("scan"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.scan"), H("scan"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("A structural recursion returns the first accepted pivot or rejects after exhausting the supplied finite list."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("scan-sound"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.scan_sound"), H("scan sound"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Every successful scan result passes the actual Boolean acceptance test."))), DescribeRole.Theorem),
