            Describe.Lean(DescribeId.Create("choose-pivot"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.choosePivot"), H("choosePivot"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The exhaustive list is passed to the verified scan; the caller provides samples, model order and uncertainty, never an inverse or a success proof."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("choose-pivot-none-iff"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.choosePivot_none_iff"), H("choosePivot none iff"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Global rejection has the precise meaning that every candidate fails the stated conservative test."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("choose-pivot-success"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.choosePivot_success"), H("choosePivot success"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("If some candidate passes the executable test, the search returns a candidate. This is completeness relative to the test, not automatic model-order identification."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("choose-pivot-certificate"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.choosePivot_certificate"), H("choosePivot certificate"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Success exposes the determinant and strict rational margin that will be consumed by the real perturbation theorem."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("result"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.Result"), H("Result"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The output contains a selected pivot and three rational matrices. No correctness or error assertion is hidden in a structure field."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("run"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.run"), H("run"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("An accepted pivot is converted into actual transition, input and output matrices. Singular or insufficiently conditioned data return none."))), DescribeRole.Definition),
