            Describe.Lean(DescribeId.Create("run-exact-recovery"), DeclarationHandle.Create("D5/S3/Observer/Hankel/ExecutableHoKalman.run_exact_recovery"), H("run exact recovery"), StatementSource.FromLean(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The actual output reproduces every Markov parameter of any order-matching reference system consistent with the noiseless input samples. The source also includes scalar reduction examples; their execution status is separate from their presence."))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S3/Observer/Hankel/FiniteHoKalmanBlocks"))]));
